void print(int fd, const char *format, ...)
{
    va_list args;
    size_t used;
    assert(fd >= 0 && fd < 8);
    used = strlen(output[fd]);
    va_start(args, format);
    vsnprintf(output[fd] + used, sizeof(output[fd]) - used, format, args);
    va_end(args);
}
